/** Chat UI: session-only history, safe text rendering, policy citations. */
import {answer} from './retrieval.mjs';
const form=document.querySelector('#chat-form'),input=document.querySelector('#question'),send=document.querySelector('#send'),log=document.querySelector('#conversation'),status=document.querySelector('#status');let policies=null;
const welcome=document.querySelector('#welcome'),back=document.querySelector('#back-to-questions'),history=document.querySelector('#view-answers');
function showAnswers(){welcome.hidden=true;log.classList.remove('home');back.hidden=false;}
function backToQuestions(){welcome.hidden=false;log.classList.add('home');back.hidden=true;history.hidden=!log.querySelector('.message');input.value='';status.textContent='Ask another question · Your previous answers are kept in this session';log.scrollTop=0;input.focus();}
back.addEventListener('click',backToQuestions);
history.addEventListener('click',()=>{showAnswers();log.scrollTop=log.scrollHeight;input.focus();});
const text=(tag,content,cls)=>{const n=document.createElement(tag);n.textContent=content;if(cls)n.className=cls;return n;};
function submit(question){if(!policies)throw Error('The policy collection is still loading.');const result=answer(question,policies);showAnswers();log.append(text('div',question,'message user'));const msg=text('div','','message assistant');msg.append(text('div','SMARTPOLICY','role'));msg.append(text('div',result.answer,'answer-body'));
 for(const source of result.sources){const card=text('div','','evidence');card.append(text('div','POLICY SOURCE','source-label'),text('h3',source.title),text('p',`Page ${source.page} · Version ${source.version}`));const a=text('a',`Read page ${source.page} in the handbook ↗`);a.href=`Demo_Company_Policy.pdf#page=${source.page}`;a.target='_blank';a.rel='noopener';card.append(a);msg.append(card);}
 if(result.abstained)msg.append(text('div','No policy determination made. Contact HR or Finance for review.','notice'));
 const again=text('button','Ask another question','back-button another-question');again.type='button';again.addEventListener('click',backToQuestions);msg.append(again);log.append(msg);input.value='';status.textContent='English questions · Each question is looked up independently';log.scrollTop=log.scrollHeight;input.focus();return result;}
form.addEventListener('submit',e=>{e.preventDefault();try{submit(input.value);}catch(e){status.textContent=e.message;}});
input.addEventListener('keydown',e=>{if(e.key==='Enter'&&!e.shiftKey&&!e.isComposing){e.preventDefault();form.requestSubmit();}});
document.querySelectorAll('[data-question]').forEach(b=>b.addEventListener('click',()=>{try{submit(b.dataset.question);}catch(e){status.textContent=e.message;}}));
try{const r=await fetch('./policies.json');if(!r.ok)throw Error('Policy collection is unavailable. Please reload the page.');policies=await r.json();if(!Array.isArray(policies)||!policies.length)throw Error('Policy collection is invalid.');input.disabled=false;send.disabled=false;status.textContent='English questions · Each question is looked up independently';}catch(e){status.textContent=e.message;}
if(document.modelContext?.registerTool){try{const lifecycle=new AbortController();Promise.resolve(document.modelContext.registerTool({name:'ask_policy_question',title:'Ask SmartPolicy',description:'Submit an English policy question and append the answer and source to the visible conversation. Each question is independent.',inputSchema:{type:'object',properties:{question:{type:'string',minLength:1,maxLength:1000}},required:['question'],additionalProperties:false},annotations:{readOnlyHint:false,untrustedContentHint:true},execute:input=>{if(!input||typeof input.question!=='string')throw Error('A question is required.');return submit(input.question);}},{signal:lifecycle.signal})).catch(()=>{});window.addEventListener('pagehide',()=>lifecycle.abort(),{once:true});}catch{}}
